package org.springframework.samples.petclinic.util;

import java.util.Map;

/**
 * Fixed region-to-postcode-range policy. A 4-digit postcode is valid for a city when it
 * falls within the inclusive range of the city's {@link CityRegion region} (NSW 2000-2099,
 * VIC 3000-3099, QLD 4000-4099). A city whose region is {@link CityRegion#UNKNOWN unknown}
 * accepts any 4-digit postcode.
 */
public final class PostcodeRange {

    /** The pinned region-to-inclusive-range table. */
    private static final Map<String, int[]> BY_REGION = Map.of(
            "NSW", new int[] {2000, 2099},
            "VIC", new int[] {3000, 3099},
            "QLD", new int[] {4000, 4099});

    private PostcodeRange() {
    }

    /**
     * Whether the given 4-digit {@code postcode} is valid for {@code city}: within the
     * inclusive range of the city's region, or unconstrained when the region is unknown.
     * Assumes {@code postcode} is a 4-digit numeric string (as enforced by the DTO pattern).
     */
    public static boolean isValidForCity(String city, String postcode) {
        int[] range = BY_REGION.get(CityRegion.locality(city));
        if (range == null) {
            return true; // no known region -> any 4-digit postcode is accepted
        }
        int value = Integer.parseInt(postcode);
        return value >= range[0] && value <= range[1];
    }
}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
import org.springframework.samples.petclinic.util.CityRegion;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "displayName", expression = "java(displayName(owner))")
    @Mapping(target = "initials", expression = "java(initials(owner))")
    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
    @Mapping(target = "locality", expression = "java(locality(owner))")
    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
    OwnerDto toOwnerDto(Owner owner);

    /** The owner's name formatted as 'LastName, FirstName' from the stored names. */
    default String displayName(Owner owner) {
        return owner.getLastName() + ", " + owner.getFirstName();
    }

    /** The upper-cased first letters of firstName and lastName, dot-separated with a
     *  trailing dot, e.g. 'J.S.'. */
    default String initials(Owner owner) {
        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
    }

    /** The membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last two digits of
     *  the registrationDate year (e.g. 'LON-SMI-0007-M26'). Null when either source field is absent. */
    default String membershipNumber(Owner owner) {
        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
            return null;
        }
        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
    }

    /** The owner's locality: the canonical region derived from its city via the fixed
     *  city-to-region table, or 'UNKNOWN' when the city is not in the table. */
    default String locality(Owner owner) {
        return CityRegion.locality(owner.getCity());
    }

    /** The owner's preferred contact method: 'EMAIL' when an email address is present,
     *  otherwise 'PHONE'. */
    default String contactPreference(Owner owner) {
        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? "EMAIL" : "PHONE";
    }

    /** The owner's derived duplicate-detection identity key: normalized telephone, email and
     *  household id joined by '|'. See {@link OwnerIdentity#key}. */
    default String identityKey(Owner owner) {
        return OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

